@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_player_update_entity_overrides_is_packet_325(version):
    assert version.PACKETS[325] is version.PlayerUpdateEntityOverridesPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_update_entity_overrides_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_update_entity_overrides_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize(
    ("update_type", "golden"),
    [
        pytest.param(v1001.UpdateType.CLEAR_OVERRIDES, V1001_CLEAR, id="clear"),
        pytest.param(v1001.UpdateType.SET_INT_OVERRIDE, V1001_INT, id="int"),
        pytest.param(v1001.UpdateType.SET_FLOAT_OVERRIDE, V1001_FLOAT, id="float"),
    ],
)
def test_v1001_gates_the_payload_on_the_update_type(update_type, golden):
    packet = v1001.PlayerUpdateEntityOverridesPacket(
        id=7, property_index=2, update_type=update_type, int_value=42, float_value=0.5
    )
    assert bytes(packet) == golden


@pytest.mark.parametrize("golden", [V1001_CLEAR, V1001_INT], ids=["clear", "int"])
def test_v2168_rejects_a_v1001_body(golden):
    with pytest.raises(ValueError, match="at byte"):
        v2168.PlayerUpdateEntityOverridesPacket.from_bytes(golden)


def test_v1001_rejects_a_v2168_body_as_trailing_bytes():
    with pytest.raises(ValueError, match="trailing bytes"):
        v1001.PlayerUpdateEntityOverridesPacket.from_bytes(V2168_CLEAR)
